DECLARE
 people jsonb := $people$[{"id":"edgar-degas","name":"Edgar Degas","name_ko":"에드가 드가","source_ids":["cma:1759"],"artwork_ids":["cma-125104","cma-135238","cma-95271","cma-135262","cma-130528"],"profile":{"lifespan":"1834–1917","context":"프랑스 · 회화·파스텔·판화","description":"프랑스의 화가로, 발레 무용수와 경마 등 동시대 파리의 장면을 관찰했습니다. 인상주의 전시에 참여하면서도 스스로를 사실주의자나 자연주의자로 여겼으며, 회화뿐 아니라 파스텔·판화·조각을 통해 움직임과 구도를 실험했습니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1946.83"}],"related_post_ids":[]}},{"id":"camille-pissarro","name":"Camille Pissarro","name_ko":"카미유 피사로","source_ids":["cma:1836"],"artwork_ids":["cma-128392","cma-155626","cma-74228","cma-109137","cma-148759"],"profile":{"lifespan":"1830–1903","context":"프랑스 · 회화·판화 · 인상주의","description":"생토마스섬에서 태어나 프랑스에서 활동한 화가로, 농촌 풍경과 일하는 사람들, 도시의 일상을 그렸습니다. 1874년 첫 인상주의 전시의 조직에 참여했으며, 야외의 빛과 대기를 짧고 분리된 색의 붓질로 포착하고 에칭과 석판화도 실험했습니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1951.356"}],"related_post_ids":[]}},{"id":"paul-gauguin","name":"Paul Gauguin","name_ko":"폴 고갱","source_ids":["cma:1776"],"artwork_ids":["cma-149410","cma-148297","cma-123168","cma-127115","cma-114196"],"profile":{"lifespan":"1848–1903","context":"프랑스 · 회화·판화 · 후기인상주의·상징주의","description":"프랑스의 화가로, 브르타뉴와 타히티 등에서 활동하며 강한 색면과 단순화한 형태를 발전시켰습니다. 인상주의 작가들과 교류한 뒤 관찰한 풍경을 기억과 상상으로 재구성하는 방향으로 나아갔고, 회화·목판화·조각·글쓰기를 함께 이어갔습니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1978.63"}],"related_post_ids":[]}},{"id":"odilon-redon","name":"Odilon Redon","name_ko":"오딜롱 르동","source_ids":["cma:1748"],"artwork_ids":["cma-148753","cma-108544","cma-135469","cma-109138","cma-115067"],"profile":{"lifespan":"1840–1916","context":"프랑스 · 회화·파스텔·판화 · 상징주의","description":"프랑스 상징주의 작가로, 꿈과 상상, 신화에서 출발한 이미지를 그렸습니다. 초기에는 목탄과 석판화의 흑백 표현에 집중했고, 1890년 이후에는 파스텔과 유채의 밝은 색을 탐구하며 인물과 꽃 정물 등을 제작했습니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1926.1976"}],"related_post_ids":[]}},{"id":"rembrandt-van-rijn","name":"Rembrandt van Rijn","name_ko":"렘브란트 판 레인","source_ids":["cma:2520"],"artwork_ids":["cma-135706","cma-144844","cma-149378","cma-136153","cma-114751"],"profile":{"lifespan":"1606–1669","context":"네덜란드 · 회화·드로잉·판화","description":"17세기 네덜란드의 화가이자 판화가입니다. 이 아카이브에서는 자화상과 성서의 장면, 무굴 회화를 참고한 드로잉을 함께 볼 수 있습니다. 선의 밀도와 인쇄판에 남긴 잉크로 빛과 어둠을 조절한 판화 작업을 소장처의 해설과 연결해 소개합니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1959.241"},{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1978.38"},{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1959.81"},{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1934.350"}],"related_post_ids":[]}},{"id":"winslow-homer","name":"Winslow Homer","name_ko":"윈슬로 호머","source_ids":["cma:3143"],"artwork_ids":["cma-106088","cma-124040","cma-131337","cma-147393","cma-123437"],"profile":{"lifespan":"1836–1910","context":"미국 · 회화·수채화","description":"미국의 화가로, 남북전쟁의 병사와 해안의 일상, 낚시와 바다를 유채와 수채화로 그렸습니다. 글로스터에서 제작한 수채화에는 어촌의 아이들과 기다리는 가족이 등장하고, 후기의 메인주 해안 그림에는 거센 파도와 변화하는 대기가 담겨 있습니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1924.195"},{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1944.524"},{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1954.128"}],"related_post_ids":[]}},{"id":"berthe-morisot","name":"Berthe Morisot","name_ko":"베르트 모리조","source_ids":["cma:1865"],"artwork_ids":["cma-128072","cma-135405","cma-148371","cma-676651","cma-703436"],"profile":{"lifespan":"1841–1895","context":"프랑스 · 회화·파스텔·수채화 · 인상주의","description":"프랑스의 인상주의 화가로, 1874년부터 인상주의 전시에 참여했습니다. 가족과 가까운 사람들의 일상을 느슨한 붓질과 빛의 변화로 그렸으며, 유화뿐 아니라 파스텔·수채화·드라이포인트 등 여러 재료와 기법을 탐구했습니다.","sources":[{"label":"클리블랜드 미술관 · 작가 정보 및 소장품 해설","url":"https://clevelandart.org/art/1950.89"}],"related_post_ids":[]}}]$people$::jsonb;
 works jsonb := $works$[{"id":"cma-125104","museum":"The Cleveland Museum of Art","title":"Frieze of Dancers","artist":"Edgar Degas (French, 1834–1917)","date":"c. 1895","medium":"oil on fabric","dimensions":"Framed: 103 x 233.5 x 7 cm (40 9/16 x 91 15/16 x 2 3/4 in.); Unframed: 70 x 200.5 cm (27 9/16 x 78 15/16 in.)","culture":"France, 19th century","accession":"1946.83","source_url":"https://clevelandart.org/art/1946.83","api_url":"https://openaccess-api.clevelandart.org/api/artworks/125104","image_url":"https://openaccess-cdn.clevelandart.org/1946.83/1946.83_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1946.83/1946.83_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"무용수들의 프리즈","description":"신발 끈을 매는 무용수를 여러 시점에서 나란히 배치한 긴 화면입니다. 미술관은 한 인물을 네 방향에서 본 장면일 가능성을 제시합니다. 흘러내린 물감과 손가락으로 찍은 흔적이 즉흥적인 표면을 만듭니다.","themes":["인물과 일상"],"artist_ids":["edgar-degas"],"artist_status":"identified","image_width":3400,"image_height":1187,"image_bytes":1193227,"sha256":"3bfc2912bc6a6da0faf7262fd510dd8344c510a8c9565e4972d0eeda80d04f79","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"직물에 유채","dimensions_ko":"액자 포함: 103 × 233.5 × 7 cm; 액자 제외: 70 × 200.5 cm"},{"id":"cma-135238","museum":"The Cleveland Museum of Art","title":"Paul Lafond and Alphonse Cherfils Examining a Painting","artist":"Edgar Degas (French, 1834–1917)","date":"c. 1878–80","medium":"oil on wood panel","dimensions":"Framed: 42.5 x 50 x 6 cm (16 3/4 x 19 11/16 x 2 3/8 in.); Unframed: 27 x 34 cm (10 5/8 x 13 3/8 in.)","culture":"France, 19th century","accession":"1958.25","source_url":"https://clevelandart.org/art/1958.25","api_url":"https://openaccess-api.clevelandart.org/api/artworks/135238","image_url":"https://openaccess-cdn.clevelandart.org/1958.25/1958.25_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1958.25/1958.25_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"그림을 살펴보는 폴 라퐁과 알퐁스 셰르필","description":"드가의 친구인 폴 라퐁과 알퐁스 셰르필이 그림을 함께 살펴보는 이중 초상입니다. 두 사람은 드가의 전시와 작품 판매를 지원했고, 화면 왼쪽 위의 헌사는 이들의 개인적 우정과 미술계의 관계를 연결합니다.","themes":["인물과 일상"],"artist_ids":["edgar-degas"],"artist_status":"identified","image_width":1148,"image_height":893,"image_bytes":680456,"sha256":"8690a28258817cf888749ceab1f9c7dad8da8464e69e42940bebea52a48ce10e","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"목판에 유채","dimensions_ko":"액자 포함: 42.5 × 50 × 6 cm; 액자 제외: 27 × 34 cm"},{"id":"cma-95271","museum":"The Cleveland Museum of Art","title":"Dancers","artist":"Edgar Degas (French, 1834–1917)","date":"c. 1896","medium":"pastel with charcoal on tracing paper mounted on paper and backed with gray board","dimensions":"Sheet: 55.7 x 41.4 cm (21 15/16 x 16 5/16 in.)","culture":"France, 19th century","accession":"1916.1043","source_url":"https://clevelandart.org/art/1916.1043","api_url":"https://openaccess-api.clevelandart.org/api/artworks/95271","image_url":"https://openaccess-cdn.clevelandart.org/1916.1043/1916.1043_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1916.1043/1916.1043_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"무용수들","description":"무대 옆에서 몸을 푸는 세 무용수를 그린 파스텔입니다. 드가는 공연의 화려함보다 대기와 연습의 순간에 주목했습니다. 노랑·주황·분홍색을 여러 겹 쌓아 만든 거친 표면은 후기 파스텔 작업의 실험을 보여줍니다.","themes":["인물과 일상"],"artist_ids":["edgar-degas"],"artist_status":"identified","image_width":671,"image_height":900,"image_bytes":355087,"sha256":"d9bf5f559b89828ac3348863bc2cae97d2870d698e81cad94d95d2474752abe8","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"종이에 붙이고 회색 보드로 보강한 트레이싱지에 파스텔과 목탄","dimensions_ko":"종이: 55.7 × 41.4 cm"},{"id":"cma-135262","museum":"The Cleveland Museum of Art","title":"Before the Race","artist":"Edgar Degas (French, 1834–1917)","date":"c. 1887–89","medium":"pastel with charcoal underdrawing on tracing paper mounted on cardboard","dimensions":"Sheet: 57.5 x 65.4 cm (22 5/8 x 25 3/4 in.)","culture":"France, 19th century","accession":"1958.27","source_url":"https://clevelandart.org/art/1958.27","api_url":"https://openaccess-api.clevelandart.org/api/artworks/135262","image_url":"https://openaccess-cdn.clevelandart.org/1958.27/1958.27_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1958.27/1958.27_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"경주 전","description":"말 위의 기수 네 명을 경주가 시작되기 전의 순간에 배치한 파스텔입니다. 미술관에 따르면 드가는 앞서 만든 구도를 뒤집어 옮기면서 기수 사이의 거리와 색채, 지평선의 나무를 조정해 이 화면을 완성했습니다.","themes":["인물과 일상"],"artist_ids":["edgar-degas"],"artist_status":"identified","image_width":1035,"image_height":893,"image_bytes":222867,"sha256":"01b4a36420dc062272cb32c37317170949aa97ae28db8975df22757ae49149ac","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"판지에 붙인 트레이싱지에 목탄 밑그림과 파스텔","dimensions_ko":"종이: 57.5 × 65.4 cm"},{"id":"cma-130528","museum":"The Cleveland Museum of Art","title":"Diego Martelli","artist":"Edgar Degas (French, 1834–1917)","date":"1879","medium":"charcoal and white chalk","dimensions":"Sheet: 44 x 31.3 cm (17 5/16 x 12 5/16 in.)","culture":"France, 19th century","accession":"1953.268","source_url":"https://clevelandart.org/art/1953.268","api_url":"https://openaccess-api.clevelandart.org/api/artworks/130528","image_url":"https://openaccess-cdn.clevelandart.org/1953.268/1953.268_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1953.268/1953.268_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"디에고 마르텔리","description":"드가를 지지한 이탈리아 미술 비평가 디에고 마르텔리를 그린 초상 연구입니다. 1879년에 제작한 여러 연구 가운데 하나로, 인상주의를 알리는 데 기여한 친구의 얼굴을 간결한 목탄 선과 밝은 초크로 표현했습니다.","themes":["인물과 일상"],"artist_ids":["edgar-degas"],"artist_status":"identified","image_width":641,"image_height":893,"image_bytes":91954,"sha256":"b483358eea11789dcc05485bf9ac6b382ca8c45b759a0f3bb7c4051a331bd7bc","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"목탄과 흰색 초크","dimensions_ko":"종이: 44 × 31.3 cm"},{"id":"cma-128392","museum":"The Cleveland Museum of Art","title":"Edge of the Woods Near L'Hermitage, Pontoise","artist":"Camille Pissarro (French, 1830–1903)","date":"1879","medium":"oil on fabric","dimensions":"Framed: 166 x 204 x 16.5 cm (65 3/8 x 80 5/16 x 6 1/2 in.); Unframed: 125 x 163 cm (49 3/16 x 64 3/16 in.)","culture":"France, 19th century","accession":"1951.356","source_url":"https://clevelandart.org/art/1951.356","api_url":"https://openaccess-api.clevelandart.org/api/artworks/128392","image_url":"https://openaccess-cdn.clevelandart.org/1951.356/1951.356_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1951.356/1951.356_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"퐁투아즈 에르미타주 근처의 숲 가장자리","description":"퐁투아즈 근처 에르미타주의 숲에서 쉬는 사람과 염소를 담은 풍경입니다. 피사로는 순수한 색의 붓질을 일정한 대각선 방향으로 엮어 빛이 스미는 숲을 구성했습니다. 이 그림은 1879년 네 번째 인상주의 전시에 출품되었습니다.","themes":["풍경과 빛"],"artist_ids":["camille-pissarro"],"artist_status":"identified","image_width":900,"image_height":690,"image_bytes":378308,"sha256":"8523ded8b988852fcb25e5b723af374730b6133875582f20615cb0cbd3674db6","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"직물에 유채","dimensions_ko":"액자 포함: 166 × 204 × 16.5 cm; 액자 제외: 125 × 163 cm"},{"id":"cma-155626","museum":"The Cleveland Museum of Art","title":"The Lock at Pontoise","artist":"Camille Pissarro (French, 1830–1903)","date":"1872","medium":"oil on fabric","dimensions":"Framed: 76.8 x 105.7 x 11.4 cm (30 1/4 x 41 5/8 x 4 1/2 in.); Unframed: 53 x 83 cm (20 7/8 x 32 11/16 in.)","culture":"France, 19th century","accession":"1990.7","source_url":"https://clevelandart.org/art/1990.7","api_url":"https://openaccess-api.clevelandart.org/api/artworks/155626","image_url":"https://openaccess-cdn.clevelandart.org/1990.7/1990.7_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/1990.7/1990.7_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","title_ko":"퐁투아즈의 수문","description":"퐁투아즈의 집 근처 수문을 흐르는 물과 흐린 하늘을 그린 풍경입니다. 빠르고 끊어진 색의 붓질이 야외의 빛과 물의 움직임을 전달합니다. 미술관은 밑그림 없이 캔버스에 바로 그린 작업 방식을 설명합니다.","themes":["풍경과 빛"],"artist_ids":["camille-pissarro"],"artist_status":"identified","image_width":900,"image_height":572,"image_bytes":225141,"sha256":"f99ff757bb656b4614a10af76089f860eb9ae9336ae0147be2cda041f2d98a30","collected_at":"2026-10-12T23:50:32.661Z","title_ko_status":"working_translation","themes_status":"editorial_classification","medium_ko":"직물에 유채","dimensions_ko":"액자 포함: 76.8 × 105.7 × 11.4 cm; 액자 제외: 53 × 83 cm"},{"id":"cma-74228","museum":"The Cleveland Museum of Art","title":"Fishmarket","artist":"Camille Pissarro (French, 1830–1903)","date":"1902","medium":"oil on canvas","dimensions":"Unframed: 66 x 81.3 cm (26 x 32 in.)","culture":"France, 20th century","accession":"2020.113","source_url":"https://clevelandart.org/art/2020.113","api_url":"https://openaccess-api.clevelandart.org/api/artworks/74228","image_url":"https://openaccess-cdn.clevelandart.org/2020.113/2020.113_print.jpg","preview_url":"https://openaccess-cdn.clevelandart.org/2020.113/2020.113_web.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"